    portras: [{"selo": "biblia", "t": "Cria em mim, ó Deus, um coração puro e renova dentro de mim um espírito firme.", "ref": "Sl 51:10"}, {"selo": "biblia", "t": "O sacrifício que agrada a Deus é um espírito quebrantado; um coração arrependido Deus não despreza.", "ref": "Sl 51:17"}, {"selo": "biblia", "t": "Lance o seu fardo sobre o Senhor, e ele o sustentará.", "ref": "Sl 55:22"}, {"selo": "liga", "t": "Pedro escreve quase a mesma coisa: lancem sobre ele toda a ansiedade, porque ele tem cuidado de vocês.", "ref": "Sl 55:22; 1Pe 5:7"}],
