    portras: [{"selo": "biblia", "t": "Deus nos abençoe, para que os seus caminhos sejam conhecidos na terra.", "ref": "Sl 67:1-2"}, {"selo": "biblia", "t": "Deus é pai dos órfãos e juiz das viúvas; ele dá uma família aos que estão sozinhos.", "ref": "Sl 68:5-6"}, {"selo": "biblia", "t": "Bendito seja o Senhor, que dia a dia leva o nosso fardo.", "ref": "Sl 68:19"}, {"selo": "liga", "t": "O Salmo 69 diz que o zelo pela casa de Deus o consumia. Os discípulos lembram disso quando Jesus purifica o templo.", "ref": "Sl 69:9; Jo 2:17"}],
