    portras: [{"selo": "biblia", "t": "Mais vale o bom nome do que muitas riquezas.", "ref": "Pv 22:1"}, {"selo": "biblia", "t": "Ensine a criança no caminho em que deve andar, e mesmo quando envelhecer não se desviará dele.", "ref": "Pv 22:6"}, {"selo": "biblia", "t": "O justo cai sete vezes e se levanta.", "ref": "Pv 24:16"}, {"selo": "biblia", "t": "Não se alegre quando o seu inimigo cair.", "ref": "Pv 24:17"}],
