  davi: { nome: 'Davi', quem: 'Filho mais novo de Jessé, de Belém; pastor, músico e rei de Israel.', vida: 'Ungido por Samuel quando cuidava das ovelhas. Tocava harpa para Saul e venceu o gigante Golias em nome do Senhor dos Exércitos, com uma funda e uma pedra.', refs: '1Sm 16:11-13,23; 17:34-50' },
  golias: { nome: 'Golias', quem: 'Guerreiro filisteu de Gate.', vida: 'Tinha seis côvados e um palmo de altura e uma armadura enorme. Durante 40 dias desafiou o exército de Israel. Foi derrubado por uma pedra da funda de Davi.', refs: '1Sm 17:4-11,16,49-50' },
  mical: { nome: 'Mical', quem: 'Filha do rei Saul; esposa de Davi.', vida: 'Amava Davi e foi dada a ele como esposa. Quando Saul mandou matar Davi, ela o desceu pela janela e o ajudou a fugir.', refs: '1Sm 18:20,27; 19:11-17' },
  abigail: { nome: 'Abigail', quem: 'Mulher de Nabal, do Carmelo de Judá; depois, esposa de Davi.', vida: 'Sensata e bonita, foi ao encontro de Davi com comida e palavras humildes e o impediu de se vingar de Nabal. Depois da morte de Nabal, casou-se com Davi.', refs: '1Sm 25:3,18-35,39-42' },
  abner: { nome: 'Abner', quem: 'Filho de Ner; primo de Saul e chefe do seu exército.', vida: 'Depois da morte de Saul, fez Isbosete rei sobre Israel. Mais tarde foi a Hebrom fazer acordo com Davi, mas foi morto por Joabe. Davi chorou na sua sepultura.', refs: '1Sm 14:50; 2Sm 2:8-9; 3:12-21,27,31-32' },
  joabe: { nome: 'Joabe', quem: 'Filho de Zeruia, sobrinho de Davi; chefe do exército.', vida: 'Comandou o exército de Davi em muitas batalhas. Era valente, mas também violento: matou Abner por vingança. Davi o pôs sobre o exército.', refs: '2Sm 2:13; 3:27; 8:16; 10:7-14' },
