  jezabel: { nome: 'Jezabel', quem: 'Filha de Etbaal, rei dos sidônios; mulher de Acabe.', vida: 'Levou Israel a servir a Baal e perseguiu os profetas do Senhor. Ameaçou Elias depois do Carmelo e armou falsas testemunhas para tomar a vinha de Nabote.', refs: '1Rs 16:31; 18:4; 19:1-2; 21:5-16' },
